CREATE FUNCTION [dbo].[Q_LIST_FROOSH_DAYLY]  (@DT1 bigint,  @DT2 bigint)  RETURNS Table   AS  RETURN ( SELECT     dbo.HEAD_LST.NUMBER, SUM(dbo.HEAD_LST.M_NAGHD) AS SumOfM_NAGHD, SUM(dbo.HEAD_LST.MABL_VAR) AS SumOfMABL_VAR,  SUM(dbo.HEAD_LST.MABL_HAV) AS SumOfMABL_HAV, SUM(dbo.HEAD_LST.MABL_HAZ) AS SumOfMABL_HAZ, SUM(dbo.HEAD_LST.TAKHFIF)  AS SumOfTAKHFIF, dbo.CUST_HESAB.NAME, dbo.HEAD_LST.DATE_N, dbo.HEAD_LST.DEPATMAN, dbo.HEAD_LST.USER_NAME,   dbo.HEAD_LST.SHIFT, dbo.HEAD_LST.TAG, dbo.CUST_HESAB.hes, dbo.CUST_HESAB.ECODE, SUM(dbo.HEAD_LST.MBAA) AS SMBAA, dbo.HEAD_LST.MOLAH, dbo.CUST_HESAB.TEL, dbo.HEAD_LST.MOIN_VAR, dbo.HEAD_LST.MOIN_HAV, dbo.HEAD_LST.MOIN_HAZ, dbo.HEAD_LST.CUST_KIND, dbo.HEAD_LST.NUMBER1, dbo.HEAD_LST.TICMBAA, dbo.HEAD_LST.TAH, dbo.HEAD_LST.MAS, dbo.HEAD_LST.VAS,  dbo.HEAD_LST.N_S, dbo.HEAD_LST.CUST_NO, dbo.HEAD_LST.M_NAGHD, dbo.HEAD_LST.MABL_VAR, dbo.HEAD_LST.MABL_HAV, dbo.HEAD_LST.MABL_HAZ, dbo.HEAD_LST.TAKHFIF, dbo.HEAD_LST.MOIN_KHF, dbo.HEAD_LST.ANBARF, dbo.HEAD_LST.FNUMCO,  dbo.HEAD_LST.SHARAYET, dbo.HEAD_LST.SGN1, dbo.HEAD_LST.SGN2, dbo.HEAD_LST.SGN3, dbo.HEAD_LST.SGN4, dbo.HEAD_LST.MBAA, dbo.HEAD_LST.HMBAA, dbo.HEAD_LST.TAMIR, dbo.HEAD_LST.TKHF, dbo.HEAD_LST.OKF, dbo.HEAD_LST.SADER, dbo.HEAD_LST.ARZD, dbo.HEAD_LST.ARZKIND, dbo.HEAD_LST.CDDATE, dbo.HEAD_LST.CDTIME, dbo.HEAD_LST.OKDATE, dbo.HEAD_LST.OKTIME, dbo.HEAD_LST.JAY, dbo.HEAD_LST.MODAT_PPID , dbo.HEAD_LST.PEPID, dbo.HEAD_LST.PEID FROM         dbo.HEAD_LST INNER JOIN  dbo.CUST_HESAB ON dbo.HEAD_LST.CUST_NO = dbo.CUST_HESAB.hes GROUP BY dbo.HEAD_LST.NUMBER, dbo.CUST_HESAB.NAME, dbo.HEAD_LST.DATE_N, dbo.HEAD_LST.DEPATMAN, dbo.HEAD_LST.USER_NAME, dbo.HEAD_LST.SHIFT, dbo.HEAD_LST.TAG, dbo.CUST_HESAB.hes, dbo.CUST_HESAB.ECODE, dbo.HEAD_LST.MOLAH, dbo.CUST_HESAB.TEL, dbo.HEAD_LST.MOIN_VAR, dbo.HEAD_LST.MOIN_HAV, dbo.HEAD_LST.MOIN_HAZ, dbo.HEAD_LST.CUST_KIND, dbo.HEAD_LST.NUMBER1, dbo.HEAD_LST.TICMBAA, dbo.HEAD_LST.TAH, dbo.HEAD_LST.MAS, dbo.HEAD_LST.VAS, dbo.HEAD_LST.N_S, dbo.HEAD_LST.CUST_NO, dbo.HEAD_LST.M_NAGHD, dbo.HEAD_LST.MABL_VAR, dbo.HEAD_LST.MABL_HAV, dbo.HEAD_LST.MABL_HAZ, dbo.HEAD_LST.TAKHFIF, dbo.HEAD_LST.MOIN_KHF, dbo.HEAD_LST.ANBARF, dbo.HEAD_LST.FNUMCO, dbo.HEAD_LST.SHARAYET, dbo.HEAD_LST.MBAA, dbo.HEAD_LST.HMBAA, dbo.HEAD_LST.TAMIR, dbo.HEAD_LST.SADER, dbo.HEAD_LST.ARZD, dbo.HEAD_LST.ARZKIND, dbo.HEAD_LST.CDDATE,  dbo.HEAD_LST.CDTIME, dbo.HEAD_LST.OKDATE, dbo.HEAD_LST.OKTIME, dbo.HEAD_LST.MODAT_PPID, dbo.HEAD_LST.PEPID, dbo.HEAD_LST.PEID,  dbo.HEAD_LST.SGN1, dbo.HEAD_LST.SGN2, dbo.HEAD_LST.SGN3, dbo.HEAD_LST.SGN4, dbo.HEAD_LST.TKHF, dbo.HEAD_LST.OKF,  dbo.HEAD_LST.JAY HAVING      (dbo.HEAD_LST.TAG = 13 OR dbo.HEAD_LST.TAG = 14) AND (dbo.HEAD_LST.DATE_N BETWEEN @DT1 AND @DT2))
